<?php
/** Plugin Name: TEMP PS S1725l petshop-dydziai-katalogas v1.2 (DP pakas ne veidas). Fazės: 1 dry, 2 deploy+kešas, 3 patikra, 9 atstatyti */
add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1725l'])) return; $f=(string)$_GET['ps_s1725l']; $r=['v'=>'S1725l','faze'=>$f]; @set_time_limit(170);
  $fp=WPMU_PLUGIN_DIR.'/petshop-dydziai-katalogas.php'; $bak=dirname(untrailingslashit(ABSPATH)).'/ps-archyvas/petshop-dydziai-katalogas.php.bak_s1725';
  $SENAS='dc4970e75efa0d51a99e7b3430e8fabd'; $NAUJAS='878ff6c4d90b0af4462940ada0ccd3a0'; $new=gzuncompress(base64_decode(''));
  $tok=function($c){ try{ token_get_all($c,TOKEN_PARSE); return 'ok'; }catch(Throwable $e){ return 'KLAIDA '.$e->getMessage(); } };
  $get=function($u){ $x=wp_remote_get($u,['timeout'=>35,'sslverify'=>false,'cookies'=>['ps_js'=>'1']]); return is_wp_error($x)?'':wp_remote_retrieve_body($x); };
  $kort=function($h){ preg_match_all('#<p class="name product-title[^"]*"><a[^>]*>([^<]+)</a>#',$h,$m); return $m[1]; };
  try{
    if($f==='1'){ $r['gyvas']=md5_file($fp); $r['sutampa']=$r['gyvas']===$SENAS; $r['naujas_ok']=md5($new)===$NAUJAS; $r['lint']=$tok($new); }
    if($f==='2'){ if(md5_file($fp)!==$SENAS && md5_file($fp)!==$NAUJAS) throw new Exception('gyvas pasikeitė'); if($tok($new)!=='ok'||md5($new)!==$NAUJAS) throw new Exception('naujas blogas');
      if(!is_file($bak)) copy($fp,$bak); file_put_contents($fp,$new); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); delete_transient('ps_dk_seimos'); if(function_exists('wp_cache_clear_cache')) wp_cache_clear_cache(); $r['md5']=md5_file($fp);
      sleep(2); $x=wp_remote_get(home_url('/?ps_hb='.time()),['timeout'=>30,'sslverify'=>false]); $r['hb']=wp_remote_retrieve_response_code($x);
      if($r['hb']!==200){ copy($bak,$fp); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); delete_transient('ps_dk_seimos'); $r['ROLLBACK']=1; } }
    if($f==='3'){
      $cl=get_term_link(get_term_by('slug','sausas-maistas-katems','product_cat')); $h=$get(add_query_arg(['filter_pakuotes_dydis'=>'2-kg','ps_nc'=>time()],$cl)); $k=$kort($h); $r['filtras_2kg']=['viso'=>count($k),'pakai'=>array_values(array_filter($k,function($x){return stripos($x,'2 vnt.')!==false;})),'rc_indoor'=>array_values(array_filter($k,function($x){return stripos($x,'INDOOR')!==false;}))];
      $k=$kort($get(add_query_arg('ps_nc',time(),$cl))); $r['sausas_katems']=['viso'=>count($k),'pakai'=>array_values(array_filter($k,function($x){return stripos($x,'2 vnt.')!==false;}))];
      $b=wp_get_post_terms(16555,'product_brand'); $k=$kort($get(add_query_arg('ps_nc',time(),get_term_link($b[0])))); $r['quattro']=['viso'=>count($k),'pakai'=>array_values(array_filter($k,function($x){return stripos($x,'2 vnt.')!==false;}))];
      $t91=get_term(91,'product_cat'); $k=$kort($get(add_query_arg('ps_nc',time(),get_term_link($t91)))); $r['dp_kategorija']=['viso'=>count($k),'pvz'=>array_slice($k,0,6)];
      $k=$kort($get(add_query_arg(['s'=>'quattro','post_type'=>'product','ps_nc'=>time()],home_url('/')))); $r['paieska_quattro']=['viso'=>count($k),'pakai'=>array_values(array_filter($k,function($x){return stripos($x,'2 vnt.')!==false;}))];
    }
    if($f==='9'){ copy($bak,$fp); if(function_exists('opcache_invalidate')) @opcache_invalidate($fp,true); delete_transient('ps_dk_seimos'); if(function_exists('wp_cache_clear_cache')) wp_cache_clear_cache(); $r['md5']=md5_file($fp); }
  }catch(Throwable $e){ $r['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($r,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE); exit;
}, 1);
